//! Exporter tests: JSON round trip over every conformance case, and Mermaid / `PlantUML` golden
//! files generated by the Python library (`create_machine(cfg, logic=stub_logic(cfg))`).
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::print_stderr)]

use std::fs;
use std::path::{Path, PathBuf};

use serde_json::Value;
use xstate_core::Machine;

/// The conformance cases live outside the crate, so the crates.io package does not contain them;
/// the tests that read them skip (with a note) instead of failing there.
fn conformance_dir() -> Option<PathBuf> {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../conformance/cases");
    if dir.is_dir() {
        return Some(dir);
    }
    eprintln!("skipping: {} is absent (a crates.io package ships only this crate)", dir.display());
    None
}

/// Conformance cases the Python library cannot render, so they have no golden file (see
/// `conformance/tools/export_golden.py`). None today: the Python library accepts multi-target
/// transitions (`031_multi_target_parallel_entry`) since its XState v5 convergence.
const NO_GOLDEN: &[&str] = &[];
/// Mermaid goldens where the Rust output deliberately differs from Python's: Python emits the
/// reserved word `end` as a node id, which Mermaid cannot parse, and Rust renames it
/// (`end_<n>`). `(case, python id, rust id)`; the golden stays exactly what Python produced and
/// the whole-word id is renamed before comparing.
const MERMAID_RESERVED_ID: &[(&str, &str, &str)] =
    &[("024_done_state_queue_order", "end", "end_3")];
/// Conformance cases in `conformance/cases`.
const EXPECTED_CASES: usize = 45;
/// Golden files in `tests/fixtures/export`: one `.mmd` and one `.puml` per case with a golden.
const EXPECTED_GOLDEN_FILES: usize = 2 * (EXPECTED_CASES - NO_GOLDEN.len());

/// `(file stem, machine config)` for every conformance case; `None` when the cases are absent.
fn conformance_machines() -> Option<Vec<(String, Value)>> {
    let dir = conformance_dir()?;
    let mut out = Vec::new();
    for entry in fs::read_dir(&dir).expect("conformance/cases exists") {
        let path = entry.expect("dir entry").path();
        if path.extension().and_then(|e| e.to_str()) != Some("json") {
            continue;
        }
        let doc: Value = serde_json::from_str(&fs::read_to_string(&path).unwrap()).unwrap();
        let stem = path.file_stem().unwrap().to_string_lossy().into_owned();
        out.push((stem, doc["machine"].clone()));
    }
    out.sort_by(|a, b| a.0.cmp(&b.0));
    Some(out)
}

/// Trailing whitespace and the final newline are not significant.
fn normalise(text: &str) -> String {
    text.replace("\r\n", "\n").lines().map(str::trim_end).collect::<Vec<_>>().join("\n")
}

#[test]
fn json_round_trips_for_every_conformance_machine() {
    let Some(cases) = conformance_machines() else { return };
    assert_eq!(cases.len(), EXPECTED_CASES, "the conformance corpus changed size");
    for (name, config) in cases {
        let machine = Machine::from_value(&config).unwrap_or_else(|e| panic!("{name}: {e}"));
        assert_eq!(machine.to_json(), config, "{name}: to_json differs from the source");
        let via_config =
            Machine::from_config(xstate_core::config::MachineConfig::from_value(&config).unwrap())
                .unwrap();
        assert_eq!(via_config.to_json(), config, "{name}: from_config lost the source");
        let again = Machine::from_value(&machine.to_json()).unwrap();
        assert_eq!(again.structure_hash(), machine.structure_hash(), "{name}: hash changed");
        assert_eq!(again.to_json(), config, "{name}: second round trip differs");
        let text = machine.to_json_string();
        let reparsed: Value = serde_json::from_str(&text).unwrap();
        assert_eq!(reparsed, config, "{name}: pretty JSON differs");
        assert!(text.contains('\n'), "{name}: to_json_string is not pretty-printed");
    }
}

/// Rename the whole-word id `from` to `to` (quoted labels such as `"end"` are untouched).
fn rename_id(text: &str, from: &str, to: &str) -> String {
    text.lines()
        .map(|line| {
            line.split(' ')
                .map(|word| if word == from { to } else { word })
                .collect::<Vec<_>>()
                .join(" ")
        })
        .collect::<Vec<_>>()
        .join(
            "
",
        )
}

fn check_golden(extension: &str, render: fn(&Machine) -> String) {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/export");
    let Some(machines) = conformance_machines() else { return };
    let mut checked = 0;
    for (name, config) in &machines {
        let golden = dir.join(format!("{name}.{extension}"));
        if NO_GOLDEN.contains(&name.as_str()) {
            assert!(!golden.exists(), "{name}.{extension} exists but is listed in NO_GOLDEN");
            continue;
        }
        let expected = fs::read_to_string(&golden).unwrap_or_else(|e| {
            panic!(
                "{name}.{extension}: no golden file ({e}); run conformance/tools/export_golden.py"
            )
        });
        let machine = Machine::from_value(config).unwrap();
        let mut expected = normalise(&expected);
        if extension == "mmd" {
            for (case, from, to) in MERMAID_RESERVED_ID {
                if case == name {
                    expected = rename_id(&expected, from, to);
                }
            }
        }
        assert_eq!(
            normalise(&render(&machine)),
            expected,
            "{name}.{extension} differs from the Python output"
        );
        checked += 1;
    }
    assert_eq!(checked, EXPECTED_CASES - NO_GOLDEN.len(), "golden .{extension} files checked");
}

/// The directory holds exactly the expected files: no stray goldens, none missing.
#[test]
fn golden_directory_holds_exactly_the_expected_files() {
    if conformance_dir().is_none() {
        return;
    }
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/export");
    let count = fs::read_dir(&dir).unwrap().count();
    assert_eq!(count, EXPECTED_GOLDEN_FILES, "files in {}", dir.display());
}

#[test]
fn mermaid_matches_python_golden_files() {
    check_golden("mmd", Machine::to_mermaid);
}

#[test]
fn plantuml_matches_python_golden_files() {
    check_golden("puml", Machine::to_plantuml);
}

#[test]
fn mermaid_uses_v4_event_names_and_delay_labels() {
    let machine = Machine::from_value(&serde_json::json!({
        "id": "m", "initial": "a",
        "states": {
            "a": {
                "after": { "500": "b", "SLOW": { "target": "b", "guard": "ok" } },
                "invoke": { "src": "svc", "id": "svc",
                            "onDone": "b", "onError": { "target": "c", "guard": "bad" } },
                "always": { "target": "b", "guard": "ready" }
            },
            "b": { "type": "final" },
            "c": {}
        }
    }))
    .unwrap();
    let text = machine.to_mermaid();
    for line in [
        "a --> b : always [ready]",
        "a --> b : after 500ms",
        "a --> b : after SLOW [ok]",
        "a --> b : invoke onDone",
        "a --> c : invoke onError [bad]",
        "b --> [*]",
    ] {
        assert!(text.lines().any(|l| l.trim() == line), "missing `{line}` in:\n{text}");
    }
}
